local ADDON_NAME, NS = ...
local MK = NS.Marking

-- What each dungeon mob casts and when, from offline data (Data/MobAbilities.lua, generated by
-- tools/gen-mob-abilities.ps1 from the cMaNGOS 1.12 world DB + Forever's spell tables). The base for Briefing
-- (kb/addons/Bulwark-Briefing.md). Covers the classic dungeons and raids; Forever-only dungeons from Warcraft Logs
-- runs (entries with wcl = true; credited in the README and the data file).
-- No events, no state: lookups only, so it works whether or not Marking is running.
local Abilities = {}
MK.Abilities = Abilities
local L, Utils = MK.L, MK.Utils

-- "11986;heal;3000;allyhp;24;24;" -> { id, kind, cast (ms), trigger, rmin, rmax (s), channel, area, kicked, arg }
-- Flags: C channelled, A area, K players interrupted it in Warcraft Logs runs (Forever dungeons), N kicks fail on it
-- (the game's data: no silence prevention type; a stun or a kill still stops it), F fear, charm or sleep (a shaman's
-- Tremor Totem removes it), U unstoppable: an instant channel that stuns, fears or confuses everyone around it as it
-- starts (Landslide's Summon Shardlings), so neither a kick nor a stun from those it hits can stop it (implies nokick).
function Abilities.ParseSpell(s)
    if type(s) ~= "string" then return nil end
    local id, kind, cast, trigger, rmin, rmax, flags, arg = strsplit(";", s)
    id = tonumber(id)
    if not id then return nil end
    flags = flags or ""
    return {
        id = id, kind = kind or "other", cast = tonumber(cast) or 0, trigger = trigger or "",
        rmin = tonumber(rmin) or 0, rmax = tonumber(rmax) or 0,
        channel = flags:find("C", 1, true) ~= nil, area = flags:find("A", 1, true) ~= nil,
        kicked = flags:find("K", 1, true) ~= nil,
        nokick = flags:find("N", 1, true) ~= nil or flags:find("U", 1, true) ~= nil,
        unstoppable = flags:find("U", 1, true) ~= nil,
        tremor = flags:find("F", 1, true) ~= nil, arg = tonumber(arg),
    }
end

-- A cast that can be stopped: it has a cast time, is channelled, or players were seen interrupting it.
function Abilities.Interruptible(spell)
    return spell.cast > 0 or spell.channel or spell.kicked == true
end

-- Stopped by a kick (Kick, Pummel, Shield Bash, Counterspell, Earth Shock), not only by a stun.
function Abilities.Kickable(spell)
    return Abilities.Interruptible(spell) and not spell.nokick
end

-- Lowercase name -> { [instanceID] = realName }, built on first use.
local index
local function Index()
    if index then return index end
    index = {}
    for instanceID, mobs in pairs(MK.MobAbilities or {}) do
        for name in pairs(mobs) do
            local key = name:lower()
            index[key] = index[key] or {}
            index[key][instanceID] = name
        end
    end
    return index
end

-- The mob's entry: in this instance if given and known there, else the first instance (lowest map ID) that has it.
-- Name match ignores case. Returns entry, realName, instanceID, or nil.
function Abilities.Find(name, instanceID)
    if type(name) ~= "string" or Utils.IsSecret(name) or name == "" then return nil end
    local hits = Index()[name:lower()]
    if not hits then return nil end
    if instanceID and hits[instanceID] then
        return MK.MobAbilities[instanceID][hits[instanceID]], hits[instanceID], instanceID
    end
    local best
    for id in pairs(hits) do if not best or id < best then best = id end end
    return MK.MobAbilities[best][hits[best]], hits[best], best
end

-- Parsed spells of an entry, in data order.
function Abilities.Spells(entry)
    local list = {}
    for _, s in ipairs(entry or {}) do
        local spell = Abilities.ParseSpell(s)
        if spell then list[#list + 1] = spell end
    end
    return list
end

local function SpellName(id)
    local name = C_Spell and C_Spell.GetSpellName and C_Spell.GetSpellName(id)
    if type(name) == "string" and not Utils.IsSecret(name) and name ~= "" then return name end
    return "#" .. id
end

-- "Healing Wave: heal, 3.0 s cast, when an ally is hurt, every 24 s, interruptible"
function Abilities.Describe(spell)
    if type(spell.id) == "string" then   -- a curated mechanic (Briefing hints): no spell behind it
        return spell.id:gsub("^@", "") .. ": " .. L["ABIL_KIND_note"]
    end
    local parts = { L["ABIL_KIND_" .. spell.kind] }
    if spell.channel then
        parts[#parts + 1] = L["ABIL_CHANNEL"]
    elseif spell.cast > 0 then
        parts[#parts + 1] = string.format(L["ABIL_CAST"], spell.cast / 1000)
    else
        parts[#parts + 1] = L["ABIL_INSTANT"]
    end
    if spell.area then parts[#parts + 1] = L["ABIL_AREA"] end
    local trig = L["ABIL_TRIG_" .. spell.trigger]
    if trig == "ABIL_TRIG_" .. spell.trigger then trig = spell.trigger end   -- no text for it: show the code
    if trig ~= "" then parts[#parts + 1] = trig:find("%%d") and string.format(trig, spell.arg or 0) or trig end
    if spell.rmax > 0 then
        parts[#parts + 1] = spell.rmin == spell.rmax and string.format(L["ABIL_EVERY"], spell.rmax)
            or string.format(L["ABIL_EVERY_RANGE"], spell.rmin, spell.rmax)
    end
    if spell.kicked then parts[#parts + 1] = L["ABIL_KICKED"]
    elseif spell.unstoppable then parts[#parts + 1] = L["ABIL_UNSTOPPABLE"]
    elseif spell.nokick and Abilities.Interruptible(spell) then parts[#parts + 1] = L["ABIL_NO_KICK"]
    elseif Abilities.Interruptible(spell) then parts[#parts + 1] = L["ABIL_INTERRUPTIBLE"] end
    if spell.tremor then parts[#parts + 1] = L["ABIL_TREMOR"] end
    return SpellName(spell.id) .. ": " .. table.concat(parts, ", ")
end

-- The target's name as far as we know it: readable (open world), learned via %t, or unique offline data name.
local function TargetName()
    if not UnitExists("target") then return nil end
    local name = UnitName("target")
    if type(name) == "string" and not Utils.IsSecret(name) then return name end
    local rec = MK.Plates and MK.Plates:RecordFor("target")
    return rec and (rec.learnedName or rec.dataName) or nil
end

-- /bwk mark abilities [name]: the named mob, else the target.
function Abilities.Report(name)
    name = name and strtrim(name) or ""
    if name == "" then name = TargetName() end
    if not name then
        MK:Print(L["ABIL_USAGE"])
        return
    end
    local entry, realName, instanceID = Abilities.Find(name, MK.Plates and MK.Plates.instanceID)
    if not entry then
        MK:Print(L["ABIL_NONE"], name)
        return
    end
    local spells = Abilities.Spells(entry)
    local where = MK.MobAbilityInstances and MK.MobAbilityInstances[instanceID] or tostring(instanceID)
    MK:Print(#spells == 1 and L["ABIL_HEADER_ONE"] or L["ABIL_HEADER"], realName, where, #spells)
    for _, spell in ipairs(spells) do print("  " .. Abilities.Describe(spell)) end
end
